"""Generated files are not linted, whether locked or opened with Edit anyway."""

from __future__ import annotations

from pathlib import Path

import pytest

pytest.importorskip("app.qt.QtWidgets", exc_type=ImportError)

from app.shell.generated_file_workflow import GeneratedFileWorkflow  # noqa: E402
from tests.support.shell_host_stubs import lint_workflow_stub  # noqa: E402

pytestmark = pytest.mark.unit

_BORDER = "#" * 80
_GENERATED = (
    "# -*- coding: utf-8 -*-\n"
    f"{_BORDER}\n"
    "## Generated from invoice.ui by ChoreBoy Code Studio. Do not edit this file:\n"
    "## it is rewritten every time the form is saved. Put your code in\n"
    "## invoice_window.py.\n"
    "## cbcs-codegen: 1\n"
    "## cbcs-body-sha256: 0\n"
    f"{_BORDER}\n"
    "x = 1\n"
)


@pytest.mark.parametrize(
    ("name", "text", "edit_anyway", "scheduled"),
    [
        ("ui_invoice.py", _GENERATED, False, 0),
        ("ui_invoice.py", _GENERATED, True, 0),
        ("ui_helpers.py", "x = 1\n", False, 1),
    ],
    ids=["locked", "edit-anyway", "no-banner"],
)
def test_lint_skips_generated_files(
    tmp_path: Path, name: str, text: str, edit_anyway: bool, scheduled: int
) -> None:
    workflow, host = lint_workflow_stub()
    path = tmp_path / name
    path.write_text(text, encoding="utf-8")
    tab = host._editor_manager.open_file(str(path)).tab
    generated_files = GeneratedFileWorkflow(
        tab_for_path=host._editor_manager.get_tab,
        refresh_tab_presentation=lambda _path: None,
    )
    generated_files.lock_from_text(tab, tab.current_content)
    if edit_anyway:
        generated_files.edit_anyway(tab.file_path)

    workflow.render_diagnostics_for_file(tab.file_path, trigger="save")

    assert len(host.background_tasks().calls) == scheduled
